/** List the events recorded for a Sentry issue, newest first. */
sdk.sentry.listIssueEvents(args: { issueId: string }): Promise<{ events: { id: string; issueId: string; timestamp: string; release: string; message: string }[] }>

/** Get who last changed a line of a file in the repository. */
sdk.github.getBlame(args: { file: string; line: number }): Promise<{ file: string; line: number; commit: string; authorName: string; authorEmail: string; committedAt: string }>

/** List the repository's commits, newest first, in pages of 50. Pass a page's nextCursor to get the next one. */
