{"code": "export async function main(input: { since: string }) {
  const counts: Record<string, number> = {};
  let cursor: string | null | undefined = undefined;
  let pages = 0;
  let total = 0;
  let oldest: string | null = null;
  let newest: string | null = null;
  while (true) {
    const page = await sdk.github.listCommits({ since: input.since, cursor: cursor ?? undefined });
    pages++;
    for (const c of page.commits) {
      total++;
      counts[c.authorEmail] = (counts[c.authorEmail] ?? 0) + 1;
      if (!newest || c.committedAt > newest) newest = c.committedAt;
      if (!oldest || c.committedAt < oldest) oldest = c.committedAt;
    }
    if (!page.nextCursor) break;
    cursor = page.nextCursor;
    if (pages > 200) throw new Error("too many pages");
  }
  return { pages, total, oldest, newest, counts };
