{"code": "export async function main(input: { since: string }) {
  const shas = new Set<string>();
  let cursor: string | undefined = undefined;
  const perPage: number[] = [];
  let boundary: string[] = [];
  while (true) {
    const page = await sdk.github.listCommits({ since: input.since, cursor });
    perPage.push(page.commits.length);
    for (const c of page.commits) {
      if (shas.has(c.sha)) throw new Error("dup " + c.sha);
      shas.add(c.sha);
      if (c.committedAt <= input.since) boundary.push(c.sha + "@" + c.committedAt);
    }
    if (!page.nextCursor) break;
    cursor = page.nextCursor;
  }
  return { perPage, unique: shas.size, boundary };
